package cn.mop.persistence;

import cn.mop.domain.*;
import cn.mop.domain.assetmetadata.*;
import cn.mop.domain.assetmetadata.ManualAssetMetadataRepository.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import com.zaxxer.hikari.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import java.sql.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.Supplier;
import static org.junit.jupiter.api.Assertions.*;

/** Real V9/runtime role only; synthetic manual drafts, no IP/source/monitoring/identity mutations. */
@EnabledIfEnvironmentVariable(named="MOP_RUN_REMOTE_TESTS",matches="true")
class PostgresManualAssetMetadataIntegrationTest {
    static final String TENANT="55000000-0000-4000-8000-000000000001",OTHER="55000000-0000-4000-8000-000000000002";
    static HikariDataSource pool;static ObjectMapper mapper;static PostgresPlatformRepository platform;static PostgresManualAssetMetadataRepository metadata;static String engineer,admin,viewer,tadmin,foreignOwner;
    @BeforeAll static void connect()throws SQLException{
        String url=System.getenv("SPRING_DATASOURCE_URL");assertNotNull(url);assertTrue(url.matches("jdbc:postgresql://127\\.0\\.0\\.1:[0-9]+/mop_test"));assertEquals("mop_test_runtime",System.getenv("SPRING_DATASOURCE_USERNAME"));var cfg=new HikariConfig();cfg.setJdbcUrl(url);cfg.setUsername(System.getenv("SPRING_DATASOURCE_USERNAME"));cfg.setPassword(System.getenv("SPRING_DATASOURCE_PASSWORD"));cfg.setMaximumPoolSize(6);cfg.setConnectionTimeout(5000);pool=new HikariDataSource(cfg);
        mapper=new ObjectMapper().registerModule(new JavaTimeModule()).setPropertyNamingStrategy(PropertyNamingStrategies.SNAKE_CASE).disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);platform=new PostgresPlatformRepository(pool,mapper);metadata=new PostgresManualAssetMetadataRepository(pool,platform,mapper);engineer=actor("msp");admin=actor("padmin");viewer=actor("viewer");tadmin=actor("tadmin");assertEquals(List.of(),metadata.readinessProblems());
        try(var c=pool.getConnection();var s=c.prepareStatement("SELECT b.user_id::text FROM public.mop_membership b WHERE b.tenant_id=?::uuid AND b.active AND NOT EXISTS(SELECT 1 FROM public.mop_membership a WHERE a.tenant_id=?::uuid AND a.user_id=b.user_id) LIMIT 1")){s.setString(1,OTHER);s.setString(2,TENANT);try(var r=s.executeQuery()){assertTrue(r.next());foreignOwner=r.getString(1);}}
    }
    @AfterAll static void close(){if(pool!=null)pool.close();}
    static String actor(String role){return platform.users().stream().filter(u->platform.membership(u.id(),TENANT).filter(m->m.role().equals(role)).isPresent()).findFirst().orElseThrow().id();}
    static Access access(String actor){return new Access(actor,TENANT,platform.membership(actor,TENANT).orElseThrow().permissionVersion(),UUID.randomUUID().toString());}
    static Asset asset(){String key=UUID.randomUUID().toString();return (Asset)platform.idempotent(engineer,TENANT,"POST /integration/manual-metadata-assets",key,"a".repeat(64),()->{Asset created=platform.insert(TENANT,engineer,"MANUAL-METADATA-"+key,"router","192.0.2.79","site-a-main");platform.audit(engineer,TENANT,"integration.manual_metadata_asset.create","asset",created.id(),"SUCCEEDED","SYNTHETIC_ONLY",key);return created;});}
    static ManualAssetMetadata facts(Asset asset,String note){return new ManualAssetMetadata(asset.name()+" revised","switch",asset.siteId(),"合成品牌","合成型号","SYNTHETIC-0001","虚构机柜",engineer,"未核验业务描述",LocalDate.of(2024,2,29),LocalDate.of(2030,1,1),null,"尚未配置采集协议",note);}
    static Object command(PostgresPlatformRepository p,Access a,String route,String key,String hash,Supplier<Object> action){return p.idempotent(a.actorId(),a.tenantId(),route,key,hash,a.permissionVersion(),action);}
    static Current update(Asset asset,long expected,ManualAssetMetadata facts){Access a=access(engineer);return (Current)command(platform,a,"PATCH /integration/manual-metadata/"+asset.id(),UUID.randomUUID().toString(),"b".repeat(64),()->metadata.update(a,asset.id(),expected,facts));}
    static long audits(String id)throws SQLException{try(var c=pool.getConnection();var s=c.prepareStatement("SELECT count(*) FROM public.mop_audit WHERE tenant_id=?::uuid AND payload->>'action'='asset.manual_metadata.update' AND payload->>'resource_id'=?")){s.setString(1,TENANT);s.setString(2,id);try(var r=s.executeQuery()){r.next();return r.getLong(1);}}}
    static JsonNode json(Object value)throws Exception{return mapper.readTree(mapper.writeValueAsBytes(value));}
    @Test void legacyManualDraftStartsWithExplicitAbsenceNotInventedMetadata(){Asset asset=asset();Current current=metadata.current(access(engineer),asset.id());assertEquals(asset,current.snapshot().asset());assertNull(current.snapshot().metadata());assertNull(current.snapshot().metadataVersion());assertNull(current.recordedBy());assertNull(current.recordedAt());assertEquals(List.of(),current.editBlockers());assertEquals(List.of(),metadata.history(access(engineer),asset.id(),10,null));}
    @Test void firstRevisionPersistsTypedFactsAndActualBeforeSnapshotWithoutChangingIpOrMonitoring()throws Exception{
        Asset asset=asset();ManualAssetMetadata facts=facts(asset,"  原始备注\n第二行\t  ");Current changed=update(asset,1,facts);assertEquals(2,changed.snapshot().asset().version());assertEquals(facts,changed.snapshot().metadata());assertEquals(2L,changed.snapshot().metadataVersion());assertEquals(asset.managementIp(),changed.snapshot().asset().managementIp());assertEquals(asset.createdAt(),changed.snapshot().asset().createdAt());assertEquals("manual",changed.snapshot().asset().source());assertEquals("DRAFT",changed.snapshot().asset().lifecycleStatus());assertEquals("unknown",changed.snapshot().asset().status());assertEquals("UNKNOWN",changed.snapshot().asset().availability());assertNull(changed.snapshot().asset().sampledAt());assertEquals("PENDING_ONBOARDING",changed.snapshot().asset().syncState());
        var revision=metadata.history(access(engineer),asset.id(),10,null).get(0);assertEquals(asset,revision.before().asset());assertNull(revision.before().metadata());assertNull(revision.previousMetadataVersion());assertEquals(facts,revision.metadata());assertEquals(1,audits(asset.id()));assertEquals(changed,new PostgresManualAssetMetadataRepository(pool,new PostgresPlatformRepository(pool,mapper),mapper).current(access(engineer),asset.id()));
    }
    @Test void subsequentChangesKeepImmutableSnapshotsAndVersionKeyset(){Asset asset=asset();var first=update(asset,1,facts(asset,"first"));var second=update(asset,2,facts(asset,"second"));var history=metadata.history(access(engineer),asset.id(),10,null);assertEquals(List.of(3L,2L),history.stream().map(Revision::assetVersion).toList());assertEquals(first.snapshot(),history.get(0).before());assertEquals(2L,history.get(0).previousMetadataVersion());assertEquals("first",history.get(1).metadata().note());assertEquals("second",second.snapshot().metadata().note());assertEquals(List.of(2L),metadata.history(access(engineer),asset.id(),10,3L).stream().map(Revision::assetVersion).toList());assertTrue(metadata.history(access(engineer),asset.id(),10,2L).isEmpty());}
    @Test void exactReplayReturnsOriginalReceiptAfterNewerRevisionWithoutDuplicateAudit()throws Exception{
        Asset asset=asset();Access a=access(engineer);String key=UUID.randomUUID().toString(),route="PATCH /integration/manual-metadata-replay/"+asset.id();Object first=command(platform,a,route,key,"a".repeat(64),()->metadata.update(a,asset.id(),1,facts(asset,"first")));update(asset,2,facts(asset,"second"));Object replay=command(platform,a,route,key,"a".repeat(64),()->{throw new AssertionError("Replay cannot execute again");});assertEquals(json(first),json(replay));assertEquals(3,metadata.current(a,asset.id()).snapshot().asset().version());assertEquals(2,audits(asset.id()));assertEquals("IDEMPOTENCY_CONFLICT",assertThrows(DomainException.class,()->command(platform,a,route,key,"b".repeat(64),()->null)).code);
    }
    @Test void staleVersionAndDuplicateNameRollbackAllChanges()throws Exception{
        Asset asset=asset(),other=asset();var first=update(asset,1,facts(asset,"first"));assertEquals("VERSION_CONFLICT",assertThrows(DomainException.class,()->update(asset,1,facts(asset,"stale"))).code);ManualAssetMetadata duplicate=new ManualAssetMetadata(other.name(),"router",asset.siteId(),null,null,null,null,null,null,null,null,null,null,"duplicate");assertEquals("ASSET_NAME_CONFLICT",assertThrows(DomainException.class,()->update(asset,2,duplicate)).code);assertEquals(first,metadata.current(access(engineer),asset.id()));assertEquals(1,audits(asset.id()));assertEquals(1,metadata.history(access(engineer),asset.id(),10,null).size());
    }
    @Test void protectedTransactionAndKnownInternalRolesAreRequired(){Asset asset=asset();assertThrows(IllegalStateException.class,()->metadata.update(access(engineer),asset.id(),1,facts(asset,"unsafe")));for(String actor:List.of(viewer,tadmin)){Access a=access(actor);assertEquals(403,assertThrows(DomainException.class,()->metadata.current(a,asset.id())).status);assertEquals(403,assertThrows(DomainException.class,()->command(platform,a,"PATCH /integration/customer-metadata",UUID.randomUUID().toString(),"a".repeat(64),()->metadata.update(a,asset.id(),1,facts(asset,"forbidden")))).status);}Access a=access(admin);Current changed=(Current)command(platform,a,"PATCH /integration/admin-metadata",UUID.randomUUID().toString(),"a".repeat(64),()->metadata.update(a,asset.id(),1,facts(asset,"admin")));assertEquals(admin,changed.recordedBy());}
    @Test void staleMembershipAndForeignObjectsAreHiddenBeforeCas(){
        Asset asset=asset();Access a=access(engineer),stale=new Access(a.actorId(),a.tenantId(),a.permissionVersion()+1,a.traceId());assertEquals(401,assertThrows(DomainException.class,()->metadata.current(stale,asset.id())).status);String foreign=platform.list(OTHER).get(0).id();assertEquals(404,assertThrows(DomainException.class,()->metadata.current(a,foreign)).status);assertEquals(404,assertThrows(DomainException.class,()->metadata.history(a,foreign,10,null)).status);
        for(String variant:List.of("owner","site")){ManualAssetMetadata invalid=new ManualAssetMetadata("synthetic","router",variant.equals("site")?"site-b-main":"site-a-main",null,null,null,null,variant.equals("owner")?foreignOwner:null,null,null,null,null,null,"reference");assertEquals(404,assertThrows(DomainException.class,()->update(asset,999,invalid)).status);}assertNull(metadata.current(a,asset.id()).snapshot().metadata());
    }
    @Test void testSeedSourceIsReadableButCannotBeSilentlyOverwritten(){Asset seeded=platform.list(TENANT).stream().filter(a->a.source().equals("test_seed")).findFirst().orElseThrow();var current=metadata.current(access(engineer),seeded.id());assertTrue(current.editBlockers().contains("MANUAL_DRAFT_REQUIRED"));assertEquals(422,assertThrows(DomainException.class,()->update(seeded,seeded.version(),facts(seeded,"no overwrite"))).status);assertEquals(seeded,platform.find(TENANT,seeded.id()).orElseThrow());}
    @Test void downstreamFailureRollsBackAssetPointerRevisionAuditAndReplay()throws Exception{
        Asset asset=asset();Access a=access(engineer);String key=UUID.randomUUID().toString(),route="PATCH /integration/manual-metadata-rollback/"+asset.id();assertThrows(IllegalStateException.class,()->command(platform,a,route,key,"a".repeat(64),()->{metadata.update(a,asset.id(),1,facts(asset,"rolled back"));throw new IllegalStateException("synthetic downstream failure");}));assertEquals(asset,metadata.current(a,asset.id()).snapshot().asset());assertNull(metadata.current(a,asset.id()).snapshot().metadata());assertTrue(metadata.history(a,asset.id(),10,null).isEmpty());assertEquals(0,audits(asset.id()));Current retried=(Current)command(platform,a,route,key,"b".repeat(64),()->metadata.update(a,asset.id(),1,facts(asset,"retry after rollback")));assertEquals(2,retried.snapshot().asset().version());assertEquals(1,audits(asset.id()));
    }
    @Test void concurrentIndependentConnectionsProduceOneMetadataRevisionAndOne409()throws Exception{
        Asset asset=asset();var executor=Executors.newFixedThreadPool(2);var ready=new CountDownLatch(2);var start=new CountDownLatch(1);
        try{List<Future<Object>> pending=new ArrayList<>();for(String note:List.of("one","two"))pending.add(executor.submit(()->{var p=new PostgresPlatformRepository(pool,mapper);var m=new PostgresManualAssetMetadataRepository(pool,p,mapper);Access a=access(engineer);ready.countDown();assertTrue(start.await(10,TimeUnit.SECONDS));try{return command(p,a,"PATCH /integration/manual-metadata-race/"+asset.id(),UUID.randomUUID().toString(),"a".repeat(64),()->m.update(a,asset.id(),1,facts(asset,note)));}catch(DomainException e){return e;}}));assertTrue(ready.await(10,TimeUnit.SECONDS));start.countDown();List<Object> results=new ArrayList<>();for(var result:pending)results.add(result.get(15,TimeUnit.SECONDS));assertEquals(1,results.stream().filter(Current.class::isInstance).count());assertEquals(1,results.stream().filter(v->v instanceof DomainException e&&e.status==409).count());assertEquals(2,metadata.current(access(engineer),asset.id()).snapshot().asset().version());assertEquals(1,metadata.history(access(engineer),asset.id(),10,null).size());assertEquals(1,audits(asset.id()));}finally{executor.shutdownNow();}
    }
    @Test void validProtocolDateBoundariesAndExplicitNullsRoundTrip(){Asset asset=asset();var facts=new ManualAssetMetadata(asset.name(),asset.type(),asset.siteId(),null,null,null,null,null,null,LocalDate.of(1,1,1),LocalDate.of(9999,12,31),null,null,"explicit nullable facts");var changed=update(asset,1,facts);assertEquals(facts,changed.snapshot().metadata());assertNull(changed.snapshot().metadata().ownerId());assertNull(changed.snapshot().metadata().collectionMethodNote());}
    @Test void siteReferencesRemainReadOnlyAndUseTheExistingCompositeFkInsteadOfBroaderGrant()throws SQLException{
        try(var c=pool.getConnection()){
            c.setAutoCommit(false);
            try(var s=c.createStatement();var r=s.executeQuery("SELECT has_table_privilege(current_user,'public.mop_site','UPDATE'),has_any_column_privilege(current_user,'public.mop_site','UPDATE')")){r.next();assertFalse(r.getBoolean(1));assertFalse(r.getBoolean(2));}
            try(var s=c.createStatement()){assertEquals("42501",assertThrows(SQLException.class,()->s.executeQuery("SELECT id FROM public.mop_site WHERE false FOR KEY SHARE")).getSQLState());}c.rollback();
        }
        Asset asset=asset();assertEquals(2,update(asset,1,facts(asset,"least-privilege reference validation")).snapshot().asset().version());
    }
}
